file.content:
            return 404, {"error": "account not found"}
        return 200, {
            "account": account,
            "balance": self.reported_balance(account),
            "confirmed_transactions": list(entry["transactions"]),
        }

# -- account state Merkle tree -------------------------------------------

def _state_tree(
    self, chain: list | None = None
) -> tuple[list[tuple[str, int, list[str]]], list[str], str]:
    """Build the confirmed account rows (ascending account), their leaves
    and the Merkle root, all from the confirmed chain under the current
    endowment. ``chain`` defaults to the whole canonical chain; a confirmed
    prefix replays historical state deterministically. Caller must hold the
    store lock.
    """
    if chain is None:
        chain = self.store.chain
    rows = self.store.account_state_rows(chain, self.initial_balance)
    leaves = [
        crypto.account_state_leaf(account, balance, transactions)
        for account, balance, transactions in rows
    ]
    return rows, leaves, crypto.account_state_root(leaves)

def get_state_root(self, height: object = None) -> tuple[int, dict]:
    """GET /v1/state/root and GET /v1/state/root/{height}.

    Without a height the tree is anchored to the highest block. A pending
    chain tip anchors nothing yet, so the endpoint returns 404 until the
    tip is confirmed.

    With a path height the state is replayed only from genesis through
    that block: the height must be an unsigned decimal without leading
    zeros (malformed heights are treated like any unknown path), the block
    must exist on the canonical chain and be confirmed — an unknown,
    non-canonical or pending height returns 404. The success body has
    exactly the same four fields as the unanchored endpoint.
    """
    with self.store.lock:
        if height is None:
            anchor = self.store.tip()
        else:
            # Strict unsigned decimal with no leading zeros, signs or
            # whitespace; every malformed value is an unknown path (404).
            height_int = _parse_decimal(height)
            if height_int is None:
                return 404, {"error": "block not found"}
            anchor = self.store.block_at(height_int)
            if anchor is None:
                return 404, {"error": "block not found"}
        if anchor.status != STATUS_CONFIRMED:
            return 404, {"error": "chain tip is pending confirmation"}
        prefix = self.store.chain if height is None else self.store.chain[: anchor.height + 1]
        rows, _leaves, root = self._state_tree(prefix)
        return 200, {
            "state_root": root,
            "height": anchor.height,
            "block_hash": anchor.block_hash,
            "account_count": len(rows),
        }

def get_account_proof(
    self, account: str, params: dict | None = None
) -> tuple[int, dict]:
    """GET /v1/accounts/{account}/proof — an inclusion proof in the
    account-state tree.

    Without ``height`` the proof is anchored to the highest (confirmed)
    block. With ``height=H`` the state is deterministically replayed from
    the canonical confirmed prefix through that block only: the value must
    be a plain non-negative decimal without leading zeros (a malformed or
    repeated query parameter is 400), and an unknown/non-canonical/pending
    anchor height is 404. ``height`` is the only accepted query parameter;
    any unknown parameter is 400. Returns 404 while a pending tip anchors
    the default view, or for an account absent from the (historical)
    confirmed account set.
    """
    height_raw: object = None
    if params is not None:
        if any(key != "height" for key in params):
            return 400, {"error": "unknown query parameter"}
        height_raw = params.get("height")
    anchor_height: int | None = None
    if height_raw is not None:
        anchor_height = _parse_decimal(height_raw)
        if anchor_height is None:
            return 400, {"error": "height must be a non-negative decimal"}
    with self.store.lock:
        if anchor_height is None:
            anchor = self.store.tip()
        else:
            anchor = self.store.block_at(anchor_height)
            if anchor is None:
                return 404, {"error": "anchor block not found"}
        if anchor.status != STATUS_CONFIRMED:
            return 404, {"error": "chain tip is pending confirmation"}
        prefix = (
            self.store.chain
            if anchor_height is None
            else self.store.chain[: anchor.height + 1]
        )
        rows, leaves, root = self._state_tree(prefix)
        index = next(
            (i for i, (name, _b, _t) in enumerate(rows) if name == account),
            None,
        )
        if index is None:
            return 404, {"error": "account not found"}
        account_name, balance, transactions = rows[index]
        siblings = crypto.merkle_proof(leaves, index)
        return 200, {
            "account": account_name,
            "balance": balance,
            "confirmed_transactions": transactions,
            "index": index,
            "state_root": root,
            "height": anchor.height,
            "block_hash": anchor.block_hash,
            "siblings": siblings,
        }

def get_account_absence_proof(
    self, account: str, params: dict | None = None
) -> tuple[int, dict]:
    """GET /v1/accounts/{account}/absence-proof — a non-membership proof
    in the account-state tree.

    Query-parameter rules are identical to :meth:`get_account_proof`:
    ``height`` is the only accepted (optional, single) parameter and must
    be a strict non-negative decimal; a malformed, repeated or unknown
    parameter is 400. An unknown/non-canonical/pending anchor height, or a
    pending default tip, is 404. When the target already occupies a row of
    the (historical) confirmed account set the answer is 409: absence is
    only provable for an account that never entered the confirmed set, and
    it says nothing about its balance.

    On success the body has the fixed key order ``account, state, lower,
    upper``: ``state`` is the state-root document
    (``state_root, height, block_hash, account_count``) and ``lower`` /
    ``upper`` are the full inclusion proofs of the confirmed accounts
    immediately before / after the target in ascending account order, or
    ``null`` on the missing side. The state anchor, account count and both
    neighbor proofs come from one canonical confirmed view snapshotted
    under the store lock; the read is pure and changes no ledger,
    generation, index or audit state.
    """
    if not isinstance(account, str) or not account:
        return 404, {"error": "account not found"}
    height_raw: object = None
    if params is not None:
        if any(key != "height" for key in params):
            return 400, {"error": "unknown query parameter"}
        height_raw = params.get("height")
    anchor_height: int | None = None
    if height_raw is not None:
        anchor_height = _parse_decimal(height_raw)
        if anchor_height is None:
            return 400, {"error": "height must be a non-negative decimal"}
    with self.store.lock:
        if anchor_height is None:
            anchor = self.store.tip()
        else:
            anchor = self.store.block_at(anchor_height)
            if anchor is None:
                return 404, {"error": "anchor block not found"}
        if anchor.status != STATUS_CONFIRMED:
            return 404, {"error": "chain tip is pending confirmation"}
        prefix = (
            self.store.chain
            if anchor_height is None
            else self.store.chain[: anchor.height + 1]
        )
        rows, leaves, root = self._state_tree(prefix)
        names = [name for name, _b, _t in rows]
        position = bisect_left(names, account)
        if position < len(names) and names[position] == account:
            return 409, {"error": "account exists in state tree"}
        state = {
            "state_root": root,
            "height": anchor.height,
            "block_hash": anchor.block_hash,
            "account_count": len(rows),
        }

        def neighbor(index: int | None) -> dict | None:
            if index is None:
                return None
            name, balance, transactions = rows[index]
            return {
                "account": name,
                "balance": balance,
                "confirmed_transactions": transactions,
                "index": index,
                "state_root": root,
                "height": anchor.height,
                "block_hash": anchor.block_hash,
                "siblings": crypto.merkle_proof(leaves, index),
            }

        lower_index = position - 1 if position > 0 else None
        upper_index = position if position < len(rows) else None
        return 200, {
            "account": account,
            "state": state,
            "lower": neighbor(lower_index),
            "upper": neighbor(upper_index),
        }

def get_attested_account_proof(
    self, account: str, params: dict | None = None
) -> tuple[int, dict]:
    """GET /v1/accounts/{account}/attested-proof — a signed state proof.

    The query-parameter rules are identical to
    :meth:`get_account_proof`: ``height`` is the only accepted (optional,
    single) parameter and must be a strict non-negative decimal; a
    malformed, repeated or unknown parameter is 400. An unknown,
    non-canonical or pending anchor, a pending default tip and an account
    absent from the (historical) confirmed set are all 404.

    On success the chain, the state tree and the current audit signer are
    snapshotted together under one store lock and the body has the fixed
    key order ``state, proof, auth``: ``state`` reuses the state-root
    document (``state_root, height, block_hash, account_count``),
    ``proof`` reuses the account-state proof document
    (``account, balance, confirmed_transactions, index, state_root,
    height, block_hash, siblings``) and ``auth`` is
    ``{key_version, signature}`` — an Ed25519 signature made with the
    current audit signer over
    ``SHA256(UTF8("ledger-state-proof-v1") || canonical_json({state,
    proof}))``.
    """
    height_raw: object = None
    if params is not None:
        if any(key != "height" for key in params):
            return 400, {"error": "unknown query parameter"}
        height_raw = params.get("height")
    anchor_height: int | None = None
    if height_raw is not None:
        anchor_height = _parse_decimal(height_raw)
        if anchor_height is None:
            return 400, {"error": "height must be a non-negative decimal"}
    from . import light_client

    with self.store.lock:
        if anchor_height is None:
            anchor = self.store.tip()
        else:
            anchor = self.store.block_at(anchor_height)
            if anchor is None:
                return 404, {"error": "anchor block not found"}
        if anchor.status != STATUS_CONFIRMED:
            return 404, {"error": "chain tip is pending confirmation"}
        prefix = (
            self.store.chain
            if anchor_height is None
            else self.store.chain[: anchor.height + 1]
        )
        rows, leaves, root = self._state_tree(prefix)
        index = next(
            (i for i, (name, _b, _t) in enumerate(rows) if name == account),
            None,
        )
        if index is None:
            return 404, {"error": "account not found"}
        account_name, balance, transactions = rows[index]
        siblings = crypto.merkle_proof(leaves, index)
        state = {
            "state_root": root,
            "height": anchor.height,
            "block_hash": anchor.block_hash,
            "account_count": len(rows),
        }
        proof = {
            "account": account_name,
            "balance": balance,
            "confirmed_transactions": transactions,
            "index": index,
            "state_root": root,
            "height": anchor.height,
            "block_hash": anchor.block_hash,
            "siblings": siblings,
        }
        signer = self.store.audit_signer
        if signer is None:
            # Every snapshot (including migrated legacy ones) carries a
            # current audit signer after recovery; reaching here is a
            # programming error rather than a client-visible condition.
            raise RuntimeError("no audit signer available for state proof")
        auth = light_client.sign_state_proof(
            signer["private_key"], signer["version"], state, proof
        )
        if auth is None:
            raise RuntimeError("current audit signer key is invalid")
        return 200, {
            "state": state,
            "proof": proof,
            "auth": auth,
        }

def get_attested_account_proofs(
    self, payload: object
) -> tuple[int, dict]:
    """POST /v1/accounts/attested-proofs — a batch of signed state proofs.

    The body must be a JSON object containing exactly ``accounts`` and
    optionally ``height``: ``accounts`` is a non-empty list of distinct
    64-lowercase-hex account ids and ``height`` (when present) uses the
    same strict form as the single-account proof query parameter. A parse
    failure, missing/extra keys, wrong types, an empty list, duplicates or
    a malformed account/height is 400 and never touches state.

    An unknown, non-canonical or pending anchor, a pending default tip or
    any requested account absent from the (historical) confirmed set is
    404. On success the chain, the state tree and the current audit signer
    are snapshotted together under one store lock and the body has the
    fixed key order ``state, proofs, auth``: ``state`` is the shared
    state-root document, ``proofs`` is one full account-state proof per
    requested account sorted by ascending account (each bound to the same
    anchor), and ``auth`` is the single audit Ed25519 signature over
    ``SHA256(UTF8("ledger-state-proofs-v1") || canonical_json({state,
    proofs}))``.
    """
    if not isinstance(payload, dict) or not set(payload) <= {"accounts", "height"}:
        return 400, {
            "error": "request body must be a JSON object with only 'accounts' and optional 'height'"
        }
    if "accounts" not in payload:
        return 400, {"error": "field 'accounts' is required"}
    accounts_raw = payload["accounts"]
    if not isinstance(accounts_raw, list) or not accounts_raw:
        return 400, {"error": "field 'accounts' must be a non-empty array"}
    if any(not crypto.is_hex64(account) for account in accounts_raw):
        return 400, {
            "error": "every account must be a string of 64 lowercase hex characters"
        }
    if len(set(accounts_raw)) != len(accounts_raw):
        return 400, {"error": "accounts must be distinct"}
    anchor_height: int | None = None
    if "height" in payload:
        anchor_height = _parse_decimal(payload["height"])
        if anchor_height is None:
            return 400, {"error": "height must be a non-negative decimal"}
    from . import light_client

    with self.store.lock:
        if anchor_height is None:
            anchor = self.store.tip()
        else:
            anchor = self.store.block_at(anchor_height)
            if anchor is None:
                return 404, {"error": "anchor block not found"}
        if anchor.status != STATUS_CONFIRMED:
            return 404, {"error": "chain tip is pending confirmation"}
        prefix = (
            self.store.chain
            if anchor_height is None
            else self.store.chain[: anchor.height + 1]
        )
        rows, leaves, root = self._state_tree(prefix)
        rows_by_account = {name: (i, name, balance, transactions)
                           for i, (name, balance, transactions) in enumerate(rows)}
        if any(account not in rows_by_account for account in accounts_raw):
            return 404, {"error": "account not found"}
        state = {
            "state_root": root,
            "height": anchor.height,
            "block_hash": anchor.block_hash,
            "account_count": len(rows),
        }
        proofs = []
        for account in sorted(set(accounts_raw)):
            index, account_name, balance, transactions = rows_by_account[account]
            siblings = crypto.merkle_proof(leaves, index)
            proofs.append({
                "account": account_name,
                "balance": balance,
                "confirmed_transactions": transactions,
                "index": index,
                "state_root": root,
                "height": anchor.height,
                "block_hash": anchor.block_hash,
                "siblings": siblings,
            })
        signer = self.store.audit_signer
        if signer is None:
            # Every snapshot (including migrated legacy ones) carries a
            # current audit signer after recovery; reaching here is a
            # programming error rather than a client-visible condition.
            raise RuntimeError("no audit signer available for state proofs")
        auth = light_client.sign_state_proofs(
            signer["private_key"], signer["version"], state, proofs
        )
        if auth is None:
            raise RuntimeError("current audit signer key is invalid")
        return 200, {
            "state": state,
            "proofs": proofs,
            "auth": auth,
        }

def confirmed_balance(self, account: str) -> int:
    """Balance from confirmed blocks only."""
    entry = self.store.accounts.get(account)
    if entry is None:
        return self.initial_balance
    return self.initial_balance + entry["received"] - entry["sent"]

